    acad_dev_up5_deviation: 'S (Rester)',
    acad_dev_up5_tc: 'TC ≥ +2',
    acad_dev_up5_why: "Sabot riche → le croupier buste plus souvent, ton 12 vaut la peine d'être conservé.",
    acad_dev_up6_dev: '12 vs 2',
    acad_dev_up6_base: 'H',
    acad_dev_up6_deviation: 'S (Rester)',
    acad_dev_up6_tc: 'TC ≥ +3',
    acad_dev_up6_why: "Même principe, seuil plus élevé car le 2 est légèrement moins dangereux pour le croupier.",
    acad_dev_down_h3: 'Déviations descendantes (≤ TC)',
    acad_dev_down_p: "Quand le TC est bas, le sabot est riche en petites cartes. Certaines actions de base ne tiennent plus :",
