    acad_dev_down1_base: 'S (Rester)',
    acad_dev_down1_deviation: 'H (Tirer)',
    acad_dev_down1_tc: 'TC ≤ 0',
    acad_dev_down1_why: "Les petites cartes ne font pas buster le croupier autant — tirer est préférable.",
    acad_dev_down2_dev: '12 vs 5',
