    acad_dev_down2_deviation: 'H (Tirer)',
    acad_dev_down2_tc: 'TC ≤ −1',
    acad_dev_down2_why: "Même logique, seuil plus bas car le 5 est déjà une carte croupier assez faible.",
    acad_dev_down3_dev: '12 vs 6',
    acad_dev_down3_base: 'S (Rester)',
    acad_dev_down3_deviation: 'H (Tirer)',
    acad_dev_down3_tc: 'TC ≤ −1',
    acad_dev_down3_why: "Idem. Le croupier avec 6 buste moins en sabot riche en petites cartes.",
    acad_dev_down4_dev: '13 vs 2',
    acad_dev_down4_base: 'S (Rester)',
    acad_dev_down4_deviation: 'H (Tirer)',
    acad_dev_down4_tc: 'TC ≤ −1',
    acad_dev_down4_why: "En sabot pauvre, le croupier améliore mieux ses mains faibles.",
    acad_dev_fab4_h3: 'Fab 4 — Surrenders par déviation',
    acad_dev_fab4_p: "Les \"Fab 4\" sont quatre surrenders conditionnels identifiés par Don Schlesinger. Ils s'ajoutent au surrender de base quand le TC monte :",
    acad_dev_fab1_hand: '16 vs 9',
