    // Academy (ES)
    acad_bases_h2: 'Bases del juego',
    acad_bases_intro: 'El blackjack es un juego de cartas donde juegas contra el crupier. El objetivo es tener una mano cuyo valor se acerque a 21 sin superarlo, y que supere la del crupier.',
    acad_bases_cards_h3: 'Valor de las cartas',
    acad_bases_card_2_9: '2 a 9', acad_bases_card_2_9_val: 'Valor nominal',
    acad_bases_card_10: '10, J, Q, K', acad_bases_card_10_val: '10 puntos',
    acad_bases_card_ace: 'As (A)', acad_bases_card_ace_val: '1 u 11 a elección',
    acad_bases_deal_h3: 'Desarrollo de una mano',
    acad_bases_deal_p1: 'El jugador y el crupier reciben dos cartas cada uno. En ENHC, el crupier solo tiene ',
    acad_bases_deal_p1_strong: 'una carta visible',
    acad_bases_deal_p1_end: '. El jugador juega primero. Luego el crupier completa su mano siguiendo reglas fijas: pide hasta alcanzar 17 o más.',
    acad_bases_actions_h3: 'Acciones posibles',
    acad_bases_action_hit: 'Pedir carta (Hit — H)', acad_bases_action_hit_desc: 'Solicitar una carta adicional. Puedes pedir tantas como quieras sin superar 21.',
    acad_bases_action_stand: 'Plantarse (Stand — S)', acad_bases_action_stand_desc: 'No pedir más. Tu mano está fija, turno del crupier.',
    acad_bases_action_double: 'Doblar (Double Down — D)', acad_bases_action_double_desc: 'Doblar la apuesta inicial. Recibes solo una carta más y paras automáticamente.',
    acad_bases_action_split: 'Separar (Split — P)', acad_bases_action_split_desc: 'Con un par, separa en dos manos independientes con apuesta igual en cada una.',
    acad_bases_action_surrender: 'Rendirse (Surrender — R)', acad_bases_action_surrender_desc: 'Renunciar a la mano a cambio de la mitad de la apuesta. Pierdes 50% en lugar de continuar. Solo si el casino lo permite.',
    acad_bases_action_insurance: 'Seguro (Insurance)', acad_bases_action_insurance_desc: 'Apuesta lateral cuando el crupier muestra un As. Apuestas hasta la mitad de tu apuesta inicial a que el crupier tiene blackjack. Recomendado solo con TC ≥ +3.',
    acad_bases_results_h3: 'Resultados posibles',
    acad_bases_result_bj: 'Blackjack', acad_bases_result_bj_desc: ': As + carta de valor 10 en dos cartas. Paga 3:2. Si el crupier también tiene BJ: empate.',
    acad_bases_result_win: 'Ganar', acad_bases_result_win_desc: ': Tu mano supera al crupier sin pasarte de 21. Paga 1:1.',
