    acad_bases_result_push: 'Empate (Push)', acad_bases_result_push_desc: ': Mismo total que el crupier. Recuperas tu apuesta.',
    acad_enhc_h2: 'La regla ENHC',
    acad_enhc_intro_strong: 'ENHC = European No Hole Card.',
    acad_enhc_intro: ' Es la regla vigente en casi todos los casinos europeos. Cambia fundamentalmente la forma de jugar respecto al blackjack americano.',
    acad_enhc_changes_h3: 'Qué cambia',
    acad_enhc_us_title: 'En blackjack americano (con carta oculta)',
    acad_enhc_us_desc: 'El crupier recibe ambas cartas desde el inicio. Con BJ, la ronda termina — los jugadores solo pierden la apuesta inicial.',
