    acad_enhc_eu_desc_pre: 'El crupier no recibe su segunda carta hasta ',
    acad_enhc_eu_desc_strong: 'que todos los jugadores hayan jugado',
    acad_enhc_eu_desc_mid: '. Si doblas o separas y el crupier tiene BJ, pierdes ',
    acad_enhc_eu_desc_strong2: 'toda tu apuesta',
    acad_enhc_eu_desc_end: '.',
    acad_enhc_impact_h3: 'Impacto en la estrategia',
    acad_enhc_impact_p: 'El riesgo de perder la apuesta doble hace que ciertos dobles no sean rentables. La estrategia ENHC difiere en tres casos:',
