    acad_enhc_hand3: '11 vs As', acad_enhc_hand3_us: 'Doblar (D) en H17', acad_enhc_hand3_enhc: 'Pedir (H)', acad_enhc_hand3_why: 'La penalización ENHC anula la ganancia esperada.',
    acad_enhc_loo_title: 'Lose Original Only (LOO)',
