    // Academy (IT)
    acad_bases_h2: 'Basi del gioco',
    acad_bases_intro: 'Il blackjack è un gioco di carte contro il croupier. Obiettivo: avere una mano vicina a 21 senza superarlo che batta il croupier.',
    acad_bases_cards_h3: 'Valore delle carte',
    acad_bases_card_2_9: '2 a 9', acad_bases_card_2_9_val: 'Valore nominale',
    acad_bases_card_10: '10, J, Q, K', acad_bases_card_10_val: '10 punti',
    acad_bases_card_ace: 'Asso (A)', acad_bases_card_ace_val: '1 o 11 a scelta',
    acad_bases_deal_h3: 'Svolgimento di una mano',
    acad_bases_deal_p1: 'Giocatore e croupier ricevono due carte ciascuno. In ENHC il croupier ha solo ',
    acad_bases_deal_p1_strong: 'una carta visibile',
    acad_bases_deal_p1_end: '. Il giocatore gioca per primo. Il croupier completa la mano seguendo regole fisse: pesca fino a 17 o più.',
    acad_bases_actions_h3: 'Azioni disponibili',
    acad_bases_action_hit: 'Pescare (Hit — H)', acad_bases_action_hit_desc: 'Richiedere una carta aggiuntiva. Puoi pescare quante volte vuoi senza superare 21.',
    acad_bases_action_stand: 'Stare (Stand — S)', acad_bases_action_stand_desc: 'Non pescare più. La mano è fissata, tocca al croupier.',
    acad_bases_action_double: 'Raddoppiare (Double Down — D)', acad_bases_action_double_desc: 'Raddoppiare la puntata iniziale. Ricevi solo una carta in più e ti fermi automaticamente.',
    acad_bases_action_split: 'Dividere (Split — P)', acad_bases_action_split_desc: 'Con una coppia, dividi in due mani indipendenti con puntata uguale su ciascuna.',
    acad_bases_action_surrender: 'Arrendersi (Surrender — R)', acad_bases_action_surrender_desc: 'Rinunciare alla mano in cambio della metà della puntata. Perdi il 50% invece di continuare. Solo se il casinò lo permette.',
    acad_bases_action_insurance: 'Assicurazione (Insurance)', acad_bases_action_insurance_desc: 'Side bet quando il croupier mostra un Asso. Punti fino alla metà della puntata che il croupier ha blackjack. Consigliato solo con TC ≥ +3.',
    acad_bases_results_h3: 'Risultati possibili',
    acad_bases_result_bj: 'Blackjack', acad_bases_result_bj_desc: ': Asso + carta da 10 in due carte. Pagato 3:2. Se anche il croupier ha BJ: pareggio.',
    acad_bases_result_win: 'Vincere', acad_bases_result_win_desc: ': La tua mano batte il croupier senza superare 21. Pagato 1:1.',
    acad_bases_result_bust: 'Sballare (Bust)', acad_bases_result_bust_desc: ': Superi 21. Perdi immediatamente.',
    acad_bases_result_push: 'Pareggio (Push)', acad_bases_result_push_desc: ': Stesso totale del croupier. Riprendi la puntata.',
    acad_enhc_h2: 'La regola ENHC',
    acad_enhc_intro_strong: 'ENHC = European No Hole Card.',
    acad_enhc_intro: ' La regola in vigore in quasi tutti i casinò europei. Cambia fondamentalmente il modo di giocare rispetto al blackjack americano.',
    acad_enhc_changes_h3: 'Cosa cambia',
    acad_enhc_us_title: 'Nel blackjack americano (con carta buca)',
    acad_enhc_us_desc: 'Il croupier riceve entrambe le carte fin dall\'inizio. Con BJ, il round finisce subito — i giocatori perdono solo la puntata iniziale.',
    acad_enhc_eu_title: 'In ENHC (senza carta buca)',
    acad_enhc_eu_desc_pre: 'Il croupier riceve la seconda carta solo ',
    acad_enhc_eu_desc_strong: 'dopo che tutti i giocatori hanno giocato',
    acad_enhc_eu_desc_mid: '. Se raddoppi o dividi e il croupier ha BJ, perdi ',
    acad_enhc_eu_desc_strong2: 'tutta la puntata',
    acad_enhc_eu_desc_end: '.',
    acad_enhc_impact_h3: 'Impatto sulla strategia',
    acad_enhc_impact_p: 'Il rischio di perdere la puntata raddoppiata rende certi raddoppi non redditizi. La strategia ENHC differisce in tre casi:',
    acad_enhc_hand1: '10 vs 10', acad_enhc_hand1_us: 'Raddoppiare (D)', acad_enhc_hand1_enhc: 'Pescare (H)', acad_enhc_hand1_why: 'Rischio di perdita doppia supera il vantaggio.',
    acad_enhc_hand2: '10 vs Asso', acad_enhc_hand2_us: 'Raddoppiare (D)', acad_enhc_hand2_enhc: 'Pescare (H)', acad_enhc_hand2_why: 'Il croupier ha troppe probabilità di BJ.',
    acad_enhc_hand3: '11 vs Asso', acad_enhc_hand3_us: 'Raddoppiare (D) in H17', acad_enhc_hand3_enhc: 'Pescare (H)', acad_enhc_hand3_why: 'La penalità ENHC annulla il guadagno atteso.',
    acad_enhc_loo_title: 'Lose Original Only (LOO)',
    acad_enhc_loo_desc: 'Variante ENHC più favorevole: con BJ del croupier perdi solo la puntata iniziale. Riduce il vantaggio della casa di ~0,11%.',
